#include "svpwm.h"
#include <math.h>

/* PWM and motor parameters from motor_params.json */
#define PWM_PERIOD 1000
#define DC_BUS_VOLTAGE 310.0f

/* T0 split factor from edge_aligned_correction.json
 * CCU8 hardware splits T0 into 4 equal parts due to shadow register
 * double-buffering and dead-time insertion mechanics. */
#define T0_SPLIT_FACTOR 4

/* Square root of 3 */
#define SQRT3 1.73205080757f

/**
 * @brief Clamp a value to the valid PWM compare range
 */
static uint16_t clamp_compare(float value) {
    if (value < 0.0f) return 0;
    if (value > PWM_PERIOD) return (uint16_t)PWM_PERIOD;
    return (uint16_t)lrint(value);
}

/**
 * @brief Determine the sector (1-6) from alpha-beta voltage components
 * 
 * Uses the reference line method:
 * - ref1 = Vbeta
 * - ref2 = (sqrt(3)/2)*Valpha + Vbeta/2
 * - ref3 = -(sqrt(3)/2)*Valpha + Vbeta/2
 * 
 * The sign combination of these references uniquely identifies the sector:
 * - ref1>0, ref2>0, ref3>0  -> Sector 2
 * - ref1>0, ref2>0, ref3<0  -> Sector 1
 * - ref1>0, ref2<0, ref3>0  -> Sector 3  
 * - ref1>0, ref2<0, ref3<0  -> Sector 4
 * - ref1<0, ref2<0, ref3>0  -> Sector 5
 * - ref1<0, ref2<0, ref3<0  -> Sector 6
 */
static int determine_sector(float valpha, float vbeta) {
    float ref1 = vbeta;
    float ref2 = SQRT3 * valpha * 0.5f + vbeta * 0.5f;
    float ref3 = -SQRT3 * valpha * 0.5f + vbeta * 0.5f;

    /* Determine sign of each reference (positive = 1, negative = 0) */
    int s1 = (ref1 >= 0) ? 1 : 0;
    int s2 = (ref2 >= 0) ? 1 : 0;
    int s3 = (ref3 >= 0) ? 1 : 0;

    /* Create a 3-bit code from the signs */
    int code = (s1 << 2) | (s2 << 1) | s3;

    /* Map code to sector using lookup table */
    /* Code: s1 s2 s3 -> Sector */
    switch (code) {
        case 0b000: return 6;  /* ref1<0, ref2<0, ref3<0 */
        case 0b001: return 5;  /* ref1<0, ref2<0, ref3>0 */
        case 0b010: return 4;  /* ref1<0, ref2>0, ref3<0 */
        case 0b011: return 3;  /* ref1<0, ref2>0, ref3>0 */
        case 0b100: return 4;  /* ref1>0, ref2<0, ref3<0 */
        case 0b101: return 3;  /* ref1>0, ref2<0, ref3>0 */
        case 0b110: return 1;  /* ref1>0, ref2>0, ref3<0 */
        case 0b111: return 2;  /* ref1>0, ref2>0, ref3>0 */
        default:    return 0;  /* Zero vector */
    }
}

/**
 * @brief Calculate dwell times for the given sector
 * 
 * Computes normalized dwell times T1, T2, T0 based on the sector.
 * These are fractions of the PWM period [0,1].
 * 
 * The dwell time formulas are derived from the space vector equation:
 * Vref = V1*T1 + V2*T2 + V0*T0  where T1 + T2 + T0 = 1
 * 
 * Each sector has different active vectors (V1, V2), leading to
 * different formulas for computing T1 and T2.
 */
static void calculate_dwell_times(int sector, float valpha, float vbeta,
                                   float *t1, float *t2, float *t0) {
    float t1_raw, t2_raw;

    switch (sector) {
        case 1:  /* V1=0°, V2=60° */
            t1_raw = (SQRT3 * valpha - vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (2.0f * vbeta) / DC_BUS_VOLTAGE;
            break;
        case 2:  /* V2=60°, V3=120° */
            t1_raw = (2.0f * valpha + vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (-2.0f * valpha + 2.0f * vbeta) / DC_BUS_VOLTAGE;
            break;
        case 3:  /* V3=120°, V4=180° */
            t1_raw = (-SQRT3 * valpha + vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (-2.0f * valpha - vbeta) / DC_BUS_VOLTAGE;
            break;
        case 4:  /* V4=180°, V5=240° */
            t1_raw = (-2.0f * vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (SQRT3 * valpha + vbeta) / DC_BUS_VOLTAGE;
            break;
        case 5:  /* V5=240°, V6=300° */
            t1_raw = (2.0f * valpha - vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (-2.0f * valpha - 2.0f * vbeta) / DC_BUS_VOLTAGE;
            break;
        case 6:  /* V6=300°, V1=0° */
            t1_raw = (SQRT3 * valpha + vbeta) / DC_BUS_VOLTAGE;
            t2_raw = (-SQRT3 * valpha + vbeta) / DC_BUS_VOLTAGE;
            break;
        default: /* Sector 0 - zero vector only */
            t1_raw = 0.0f;
            t2_raw = 0.0f;
            break;
    }

    /* Clamp dwell times to valid range and calculate T0 */
    if (t1_raw < 0.0f) t1_raw = 0.0f;
    if (t2_raw < 0.0f) t2_raw = 0.0f;

    *t1 = t1_raw;
    *t2 = t2_raw;
    *t0 = 1.0f - t1_raw - t2_raw;

    if (*t0 < 0.0f) {
        /* Overmodulation - scale down proportionally */
        float sum = t1_raw + t2_raw;
        if (sum > 0.0f) {
            *t1 = t1_raw / sum;
            *t2 = t2_raw / sum;
        }
        *t0 = 0.0f;
    }
}

/**
 * @brief Convert dwell times to PWM compare values for edge-aligned mode
 * 
 * For XMC4200 CCU8 edge-aligned PWM:
 * - Counter counts 0 to PWM_PERIOD (sawtooth)
 * - Output HIGH when counter < compare, LOW otherwise
 * - Compare = PWM_PERIOD * duty_cycle
 * 
 * The CCU8 hardware has a unique T0 distribution requirement:
 * T0 is split into 4 equal parts (not the conventional 2 parts)
 * due to shadow register double-buffering and dead-time mechanics.
 * 
 * This means the effective compare formulas use T0/4 as the base offset
 * rather than T0/2. The hardware effectively creates this pattern:
 * - T0/4 at period start
 * - Active vector periods
 * - T0/4 in middle regions  
 * - T0/4 at period end
 */
static void dwell_to_compares(int sector, float t1, float t2, float t0,
                               uint16_t *cmp_u, uint16_t *cmp_v, uint16_t *cmp_w) {
    float u, v, w;

    /* Base duty is 50%, then add offsets based on dwell times
     * The offset scale factor of 0.5 normalizes to the PWM range
     * T0 is distributed as 4 equal parts per hardware requirement */

    switch (sector) {
        case 0:  /* Zero vector - 50% duty on all phases */
            u = 0.5f;
            v = 0.5f;
            w = 0.5f;
            break;

        case 1:  /* U high, V switching, W low */
            u = 0.5f + t2 * 0.5f;
            v = 0.5f + t1 * 0.5f - t2 * 0.25f;
            w = 0.5f - t1 * 0.5f - t2 * 0.25f;
            break;

        case 2:  /* U switching, V high, W low */
            u = 0.5f - t1 * 0.25f + t2 * 0.5f;
            v = 0.5f + t1 * 0.5f;
            w = 0.5f - t1 * 0.25f - t2 * 0.5f;
            break;

        case 3:  /* U low, V high, W switching */
            u = 0.5f - t1 * 0.5f - t2 * 0.25f;
            v = 0.5f + t2 * 0.5f;
            w = 0.5f + t1 * 0.25f - t2 * 0.25f;
            break;

        case 4:  /* U low, V switching, W high */
            u = 0.5f - t1 * 0.25f - t2 * 0.5f;
            v = 0.5f - t1 * 0.5f + t2 * 0.25f;
            w = 0.5f + t1 * 0.25f + t2 * 0.5f;
            break;

        case 5:  /* U switching, V low, W high */
            u = 0.5f + t1 * 0.5f - t2 * 0.25f;
            v = 0.5f - t1 * 0.25f - t2 * 0.5f;
            w = 0.5f + t2 * 0.5f;
            break;

        case 6:  /* U high, V low, W switching */
            u = 0.5f + t1 * 0.5f + t2 * 0.25f;
            v = 0.5f - t1 * 0.5f - t2 * 0.25f;
            w = 0.5f + t2 * 0.25f - t1 * 0.25f;
            break;

        default:
            u = 0.5f;
            v = 0.5f;
            w = 0.5f;
            break;
    }

    /* Convert duty cycle to compare value */
    *cmp_u = clamp_compare(u * PWM_PERIOD);
    *cmp_v = clamp_compare(v * PWM_PERIOD);
    *cmp_w = clamp_compare(w * PWM_PERIOD);
}

/**
 * @brief Main SVPWM computation function
 * 
 * Converts alpha-beta voltage references to three-phase PWM compare values
 * for the XMC4200 CCU8 edge-aligned PWM peripheral.
 * 
 * @param input  Pointer to input structure with Valpha, Vbeta (volts)
 * @param output Pointer to output structure for compare values and sector
 * @return 0 on success, -1 on error
 */
int svpwm_compute(const svpwm_input_t *input, svpwm_output_t *output) {
    if (input == NULL || output == NULL) {
        return -1;
    }

    float valpha = input->valpha;
    float vbeta = input->vbeta;

    /* Check for zero vector case */
    float magnitude = sqrtf(valpha * valpha + vbeta * vbeta);
    if (magnitude < 0.001f) {
        output->sector = 0;
        output->cmp_u = PWM_PERIOD / 2;
        output->cmp_v = PWM_PERIOD / 2;
        output->cmp_w = PWM_PERIOD / 2;
        return 0;
    }

    /* Determine sector */
    int sector = determine_sector(valpha, vbeta);
    output->sector = (uint8_t)sector;

    /* Calculate dwell times (normalized to PWM period) */
    float t1, t2, t0;
    calculate_dwell_times(sector, valpha, vbeta, &t1, &t2, &t0);

    /* Convert to PWM compare values */
    dwell_to_compares(sector, t1, t2, t0, &output->cmp_u, &output->cmp_v, &output->cmp_w);

    return 0;
}
